using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.TwistedGround;
internal sealed class OriginalGaussianExternalEquationsDocument : IScribeDocumentDefinition
{
 public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
  "Literal Two-Variable Frequency and Displacement Equations", H("Literal Two-Variable Frequency and Displacement Equations"), Blocks(
   Paragraph(Text("The actual ordinary bilinear transpose transports the first-variable frequency certificate to the second variable.")),
   Describe.Lean(DescribeId.Create("literal-symmetry"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalEquations.literal_symmetry"), H("literal_symmetry"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For either original J or full T and every signed mode pair, ordinary bilinear symmetry interchanges the two external modes throughout the unit disk. The original transpose proof is reused to match the positive candidate crossing column."))), DescribeRole.Theorem),
   Describe.Lean(DescribeId.Create("first-mode-derivative"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalEquations.firstModeDerivative"), H("firstModeDerivative"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For either kernel and sign pair and complex u,v,z, this is u(1-u) times the first partial derivative plus delta(e,u) times the literal kernelMode, before subtracting the actual zero-row correction. Delta is (1-3u)/2 for the positive sign and -(u+1)/2 for the negative sign."))), DescribeRole.Definition),
   Describe.Lean(DescribeId.Create("second-mode-derivative"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalEquations.secondModeDerivative"), H("secondModeDerivative"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For either kernel and sign pair and complex u,v,z, this is v(1-v) times the second partial derivative plus delta(f,v) times the literal kernelMode, before subtracting the actual zero-row correction."))), DescribeRole.Definition),
   Describe.Lean(DescribeId.Create("second-frequency"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalEquations.second_frequency"), H("second_frequency"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every signed J/T kernel and every point in the joint normal-convergence disk, the second external frequency series equals the second-mode differential operator together with its actual opposite-sign zero-row correction."))), DescribeRole.Theorem),
   Describe.Lean(DescribeId.Create("displacement-with-boundary"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalEquations.displacement_with_boundary"), H("displacement_with_boundary"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For all signed inputs and outputs and real 0<r<1, the original J sum of the two frequency actions and the original T difference of the two frequency actions equal the compiled source displacement products, while retaining the literal negative-zero row corrections."))), DescribeRole.Theorem),
   Describe.Lean(DescribeId.Create("displacement-differential"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/OriginalGaussianExternalEquations.displacement_differential"), H("displacement_differential"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For every sign pair and real 0<r<1, with norm(u)+sqrt(r)<1 and norm(v)+sqrt(r)<1, the original J satisfies modeScale(f,v) D_u J + modeScale(e,u) D_v J = (1-r) M_e(u) M_f(v) [a_e(u) h_f(v)+h_e(u) a_f(v)]/2 + modeB(e) modeB(f). The original full T satisfies the corresponding difference equation with a_e h_f-h_e a_f and no constant term. Here D_u and D_v are the two scaled frequency differential operators, M is the actual sourceMode, a is modeA, h is modeH with the original period logarithmic derivative, and the T identity contribution is retained."))), DescribeRole.Theorem))));
